using DDHI.Pharmacy.Domain;
using DDHI.Pharmacy.Contracts;
using DDHI.Pharmacy.Infrastructure;
using DDHI.Pharmacy.Application;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.EntityFrameworkCore;
using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Xunit;
public class Factory:WebApplicationFactory<Program> {
 protected override void ConfigureWebHost(IWebHostBuilder b){b.UseEnvironment("Development");b.UseSetting("ConnectionStrings:Pharmacy",Environment.GetEnvironmentVariable("DDHI_TEST_CONNECTION")??throw new InvalidOperationException("DDHI_TEST_CONNECTION required; use isolated test database."));}
}
public class WorkflowTests: IAsyncLifetime {
 readonly Factory factory=new();HttpClient chief=null!,admin=null!,reader=null!;
 public async Task InitializeAsync(){
  using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();Safety.Require((db.Database.GetDbConnection().Database.StartsWith("ddhi_test")||db.Database.GetDbConnection().Database.StartsWith("ddhi_restore_")),"Refuse non-test database.");await db.Database.MigrateAsync();
  var roles=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();foreach(var role in Roles.All)if(!await roles.RoleExistsAsync(role))await roles.CreateAsync(new IdentityRole(role));
  chief=await User(Roles.Chief);admin=await User(Roles.SystemAdmin);reader=await User(Roles.Reader);
 }
 async Task<HttpClient> User(string role){using var scope=factory.Services.CreateScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<PharmacyUser>>();var email=Guid.NewGuid()+"@test.invalid";var u=new PharmacyUser{Email=email,UserName=email,EmailConfirmed=true};Assert.True((await users.CreateAsync(u,"Test-Only!Password123")).Succeeded);await users.AddToRoleAsync(u,role);var c=factory.CreateClient();var login=await c.PostAsJsonAsync("/auth/login",new{email,password="Test-Only!Password123"});Assert.Equal(HttpStatusCode.OK,login.StatusCode);var token=await login.Content.ReadFromJsonAsync<JsonElement>();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token.GetProperty("accessToken").GetString());c.DefaultRequestHeaders.Add("X-Workstation",Guid.NewGuid().ToString());return c;}
 async Task<JsonElement> Post(HttpClient c,string path,object data,string? key=null){using var req=new HttpRequestMessage(HttpMethod.Post,"/api/"+path){Content=JsonContent.Create(data)};req.Headers.Add("Idempotency-Key",key??Guid.NewGuid().ToString());var r=await c.SendAsync(req);var text=await r.Content.ReadAsStringAsync();Assert.True(r.IsSuccessStatusCode,$"{path}: {r.StatusCode}: {text}");return JsonSerializer.Deserialize<JsonElement>(text);}
 async Task<HttpResponseMessage> Raw(HttpClient c,string path,object data){var req=new HttpRequestMessage(HttpMethod.Post,"/api/"+path){Content=JsonContent.Create(data)};req.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());return await c.SendAsync(req);}
 async Task<(Guid Medicine,Guid Balance,Guid Batch,Guid Location)> Stock(decimal qty=1,int days=365){var med=await Post(chief,"medicines",new MedicineInput("Test "+Guid.NewGuid(),"","10 mg","tablet","oral","","","tablet",1));var mid=med.GetProperty("Id").GetGuid();var loc=await Post(chief,"locations",new NamedInput("Loc "+Guid.NewGuid()));var lid=loc.GetProperty("Id").GetGuid();var supplier=await Post(chief,"suppliers",new NamedInput("Supplier "+Guid.NewGuid()));var receipt=await Post(chief,"receiving",new ReceiveInput(mid,lid,supplier.GetProperty("Id").GetGuid(),Guid.NewGuid().ToString(),"LOT",Safety.Today.AddDays(days),qty,1,2,true));return(mid,receipt.GetProperty("BalanceId").GetGuid(),receipt.GetProperty("Id").GetGuid(),lid);}
 async Task<Guid> Order(Guid mid,decimal qty=1){var r=await Post(chief,"orders",new OrderInput(Guid.NewGuid().ToString(),"test-encounter",mid,qty,true));return r.GetProperty("Id").GetGuid();}
 async Task Policy()=>await Post(chief,"settings",new SettingInput("ManualDispensingApproved","true","TEST ONLY written policy"));
 public Task DisposeAsync(){chief?.Dispose();admin?.Dispose();reader?.Dispose();factory.Dispose();return Task.CompletedTask;}
 [Fact]public async Task AnonymousDenied(){using var c=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/inventory")).StatusCode);}
 [Fact]public async Task ReaderCannotReceive(){Assert.Equal(HttpStatusCode.Forbidden,(await Raw(reader,"receiving",new{})).StatusCode);}
 [Fact]public async Task TechnicalAdministratorCannotDispense(){Assert.Equal(HttpStatusCode.Forbidden,(await Raw(admin,"dispensing",new{})).StatusCode);}
 [Fact]public async Task ConcurrentFinalUnitOnlyOnce(){await Policy();var stock=await Stock();var one=await Order(stock.Medicine);var two=await Order(stock.Medicine);var responses=await Task.WhenAll(Raw(chief,"dispensing",new DispenseInput(one,stock.Balance,1,"","ManualSelection",true,true,"TEST approval")),Raw(chief,"dispensing",new DispenseInput(two,stock.Balance,1,"","ManualSelection",true,true,"TEST approval")));Assert.Single(responses,x=>x.IsSuccessStatusCode);Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.Conflict);}
 [Fact]public async Task WrongMedicineBlocked(){await Policy();var a=await Stock();var b=await Stock();var order=await Order(a.Medicine);var r=await Raw(chief,"dispensing",new DispenseInput(order,b.Balance,1,"","ManualSelection",true,true,"approved"));Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}
 [Fact]public async Task PhysicalScanCannotBeAsserted(){await Policy();var a=await Stock();var order=await Order(a.Medicine);Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"dispensing",new DispenseInput(order,a.Balance,1,"","PhysicalDevice",true,true,"approved"))).StatusCode);}
 [Fact]public async Task RecallBlocksDispensing(){await Policy();var a=await Stock();await Post(chief,"recalls",new RecallInput(a.Batch,Guid.NewGuid().ToString(),"test recall",true));var order=await Order(a.Medicine);Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"dispensing",new DispenseInput(order,a.Balance,1,"","ManualSelection",true,true,"approved"))).StatusCode);}
 [Fact]public async Task IdempotencyReturnsSameResult(){var request=new NamedInput("Idempotent "+Guid.NewGuid());var key=Guid.NewGuid().ToString();var a=await Post(chief,"suppliers",request,key);var b=await Post(chief,"suppliers",request,key);Assert.Equal(a.GetProperty("Id").GetGuid(),b.GetProperty("Id").GetGuid());}
 [Fact]public async Task UnconfirmedReceivingBlocked(){var a=await Stock();var r=await Raw(chief,"counts",new CountInput(a.Balance,0,"test","test",false));Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);}
 [Fact]public async Task NegativeCountBlocked(){var a=await Stock();Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"counts",new CountInput(a.Balance,-1,"test","test",true))).StatusCode);}
 [Fact]public async Task TransferPreservesLedger(){var a=await Stock(5);var dest=await Post(chief,"locations",new NamedInput("Dest "+Guid.NewGuid()));await Post(chief,"transfers",new MoveInput(a.Balance,dest.GetProperty("Id").GetGuid(),2,"transfer "+Guid.NewGuid(),"test",true));await Post(chief,"reconciliation",new{});var response=await chief.GetFromJsonAsync<JsonElement>("/api/reconciliation");Assert.Empty(response.EnumerateArray());}
 [Fact]public async Task AuditChainValid(){await Post(chief,"suppliers",new NamedInput("Audit "+Guid.NewGuid()));var r=await chief.GetFromJsonAsync<JsonElement>("/api/audit/verify");Assert.True(r.GetProperty("valid").GetBoolean());}
 [Fact]public async Task LedgerDatabaseRejectsUpdate(){var a=await Stock();using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"StockMovements\" SET \"Delta\" = 999 WHERE \"BalanceId\" = {a.Balance}"));}

 [Theory][InlineData("inventory")][InlineData("dashboard")][InlineData("barcodes")][InlineData("scanners")][InlineData("workstations")][InlineData("reports/inventory")][InlineData("reports/low-stock")][InlineData("reports/near-expiry")][InlineData("reports/expired")][InlineData("reports/valuation")][InlineData("reports/receiving")][InlineData("reports/dispensing")][InlineData("reports/movements")][InlineData("reports/traceability")][InlineData("reports/adjustments")][InlineData("reports/recalls")][InlineData("reports/integration")][InlineData("reports/failed-transactions")][InlineData("reports/reconciliation")][InlineData("reports/user-activity")]
 public async Task ReadEndpointsWork(string path){var response=await chief.GetAsync("/api/"+path);Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());}
 [Fact]public async Task ExpiredStockBlocked(){await Policy();var a=await Stock();using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();var batch=await db.InventoryBatchs.SingleAsync(x=>x.Id==a.Batch);batch.Expiration=Safety.Today.AddDays(-1);await db.SaveChangesAsync();}var order=await Order(a.Medicine);Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"dispensing",new DispenseInput(order,a.Balance,1,"","ManualSelection",true,true,"test"))).StatusCode);}
 [Fact]public async Task DisabledManualPolicyBlocks(){await Post(chief,"settings",new SettingInput("ManualDispensingApproved","false","test disabled"));var a=await Stock();var order=await Order(a.Medicine);Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"dispensing",new DispenseInput(order,a.Balance,1,"","ManualSelection",true,true,"test"))).StatusCode);}
 [Fact]public async Task UnverifiedPatientBlocks(){await Policy();var a=await Stock();var order=await Order(a.Medicine);Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"dispensing",new DispenseInput(order,a.Balance,1,"","ManualSelection",false,true,"test"))).StatusCode);}
 [Fact]public async Task ReturnQuarantinedAndCannotExceedDispense(){await Policy();var a=await Stock();var order=await Order(a.Medicine);var tx=await Post(chief,"dispensing",new DispenseInput(order,a.Balance,1,"","ManualSelection",true,true,"test"));Guid lineId;using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();var id=tx.GetProperty("Id").GetGuid();lineId=(await db.DispenseTransactionLines.SingleAsync(x=>x.TransactionId==id)).Id;}await Post(chief,"returns",new ReturnInput(lineId,1,"return-test","quality review",true));Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"returns",new ReturnInput(lineId,1,"duplicate-return","test",true))).StatusCode);using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();Assert.Equal(1,await db.InventoryBalances.Where(x=>x.BatchId==a.Batch&&x.Status==StockStatus.Quarantined).SumAsync(x=>x.Quantity));}}
 [Fact]public async Task FourConcurrentRequestsOneFinalUnit(){await Policy();var a=await Stock();var orders=new List<Guid>();for(int i=0;i<4;i++)orders.Add(await Order(a.Medicine));var results=await Task.WhenAll(orders.Select(o=>Raw(chief,"dispensing",new DispenseInput(o,a.Balance,1,"","ManualSelection",true,true,"test"))));Assert.Single(results,r=>r.IsSuccessStatusCode);Assert.Equal(3,results.Count(r=>r.StatusCode==HttpStatusCode.Conflict));}
 [Fact]public async Task DatabaseRejectsNegativeBalance(){var a=await Stock();using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"InventoryBalances\" SET \"Quantity\"=-1 WHERE \"Id\"={a.Balance}"));}
 [Fact]public async Task FefoExcludesRecalled(){var a=await Stock();await Post(chief,"recalls",new RecallInput(a.Batch,Guid.NewGuid().ToString(),"test",true));var rows=await chief.GetFromJsonAsync<JsonElement>("/api/fefo/"+a.Medicine);Assert.Empty(rows.EnumerateArray());}
 [Fact]public async Task InvalidBearerDenied(){using var c=factory.CreateClient();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer","invalid");Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/inventory")).StatusCode);}

 async Task<decimal> Quantity(Guid id){using var scope=factory.Services.CreateScope();return await scope.ServiceProvider.GetRequiredService<PharmacyDb>().InventoryBalances.Where(x=>x.Id==id).Select(x=>x.Quantity).SingleAsync();}
 [Fact]public async Task AdjustmentReversalIsLinkedAndSingleUse(){var a=await Stock(3);await Post(chief,"counts",new CountInput(a.Balance,5,Guid.NewGuid().ToString(),"authorized count",true));Guid movement;using(var scope=factory.Services.CreateScope()){movement=await scope.ServiceProvider.GetRequiredService<PharmacyDb>().StockMovements.Where(x=>x.BalanceId==a.Balance&&x.Kind=="CountAdjustment").Select(x=>x.Id).SingleAsync();}await Post(chief,"movements/"+movement+"/reverse",new ReasonInput("Authorized correction",true));Assert.Equal(3,await Quantity(a.Balance));Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"movements/"+movement+"/reverse",new ReasonInput("Duplicate correction",true))).StatusCode);}
 [Fact]public async Task TransferReversalRestoresBothLocations(){var a=await Stock(5);var dest=await Post(chief,"locations",new NamedInput("Reverse destination "+Guid.NewGuid()));var reference=Guid.NewGuid().ToString();await Post(chief,"transfers",new MoveInput(a.Balance,dest.GetProperty("Id").GetGuid(),2,reference,"test",true));Guid movement;using(var scope=factory.Services.CreateScope()){movement=await scope.ServiceProvider.GetRequiredService<PharmacyDb>().StockMovements.Where(x=>x.Reference==reference&&x.Kind=="TransferOut").Select(x=>x.Id).SingleAsync();}await Post(chief,"movements/"+movement+"/reverse",new ReasonInput("Authorized transfer correction",true));Assert.Equal(5,await Quantity(a.Balance));}
 [Fact]public async Task QuarantineReleaseRequiresChiefAndClearBatch(){var a=await Stock(2);var held=await Post(chief,"stock-status",new StockStateInput(a.Balance,"Quarantined",2,Guid.NewGuid().ToString(),"QA hold",true));var heldId=held.GetProperty("TargetBalanceId").GetGuid();await Policy();var order=await Order(a.Medicine);Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"dispensing",new DispenseInput(order,heldId,1,"","ManualSelection",true,true,"test"))).StatusCode);await Post(chief,"stock-status",new StockStateInput(heldId,"Available",2,Guid.NewGuid().ToString(),"Approved quality release",true));Assert.Equal(2,await Quantity(a.Balance));}
 [Fact]public async Task RecalledBatchCannotBeReleased(){var a=await Stock();var held=await Post(chief,"stock-status",new StockStateInput(a.Balance,"Quarantined",1,Guid.NewGuid().ToString(),"hold",true));await Post(chief,"recalls",new RecallInput(a.Batch,Guid.NewGuid().ToString(),"recall",true));Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"stock-status",new StockStateInput(held.GetProperty("TargetBalanceId").GetGuid(),"Available",1,Guid.NewGuid().ToString(),"requested release",true))).StatusCode);}
 [Fact]public async Task RecallClosesOnlyAfterDisposition(){var a=await Stock();var recall=await Post(chief,"recalls",new RecallInput(a.Batch,Guid.NewGuid().ToString(),"recall",true));var id=recall.GetProperty("Id").GetGuid();Assert.Equal(HttpStatusCode.Conflict,(await Raw(chief,"recalls/"+id+"/close",new ReasonInput("requested closure",true))).StatusCode);await Post(chief,"disposals",new DisposeInput(a.Balance,1,Guid.NewGuid().ToString(),"Authorized physical supplier return",true));await Post(chief,"recalls/"+id+"/close",new ReasonInput("Verified zero stock and approved disposition",true));Assert.Equal(0,await Quantity(a.Balance));}
 [Fact]public async Task ReaderCannotDisposeStock(){var a=await Stock();Assert.Equal(HttpStatusCode.Forbidden,(await Raw(reader,"disposals",new DisposeInput(a.Balance,1,"test","test",true))).StatusCode);}
 [Fact]public async Task ScannerProfileCanBeDisabledWithoutRebuild(){var station=await Post(chief,"workstations",new WorkstationInput("Scanner config test "+Guid.NewGuid()));var w=station.GetProperty("Id").GetGuid();var profile=await Post(chief,"scanners",new ScannerInput(w,"Optional HID",true,"HID","","Enter"));var id=profile.GetProperty("Id").GetGuid();var result=await Post(chief,"scanners/"+id+"/configure",new ScannerInput(w,"Optional HID",false,"HID","","Enter"));Assert.False(result.GetProperty("Enabled").GetBoolean());}

 [Fact]public async Task BulkCsvImportUsesBoundedAuditSummary(){var prefix=Guid.NewGuid().ToString("N");var csv="CerebroMedicineId,GenericName,BrandName,Strength,DosageForm,Route,Manufacturer,Category,BaseUnit,ReorderLevel\n"+string.Join("\n",Enumerable.Range(0,50).Select(i=>$"{prefix}-{i},Bulk medicine {i},,TEST,tablet,oral,,TEST ONLY,tablet,1"));var result=await Post(chief,"imports/medicines",new{csv,approvalReference="TEST ONLY approved catalog",confirmed=true});Assert.Equal(50,result.GetProperty("imported").GetInt32());using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<PharmacyDb>();var latest=await db.AuditEvents.OrderByDescending(x=>x.CreatedAt).FirstAsync();Assert.Contains("Large payload summarized",latest.Detail);Assert.True(latest.Detail.Length<2000);}
}
